\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb,amsthm,booktabs,array,hyperref,microtype}
\usepackage[T1]{fontenc}
\usepackage{lmodern}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\title{Inverse Stereographic Renormalization for the\\One-Dimensional Ising Decimation Map}
\author{Aristotle}
\date{July 29, 2026}

\begin{document}
\maketitle

\begin{abstract}
We develop an exact geometric representation of the zero-field one-dimensional Ising decimation transformation. In the high-temperature coordinate $g=\tanh K$, decimation of alternate spins is $R(g)=g^2$. We compactify the coupling line by inverse stereography,
\[
S(g)=\left(\frac{2g}{1+g^2},\frac{1-g^2}{1+g^2}\right),
\]
and prove that it conjugates the Ising map to the rational circle transformation
\[
C(x,y)=\left(\frac{x^2}{2-x^2},\frac{2y}{1+y^2}\right).
\]
We characterize the finite fixed couplings as exactly $0$ and $1$, define the discrete one-step beta observable $B(g)=R(g)-g$, and compute $R'(g)=2g$ and $B'(g)=2g-1$. This gives a global bridge between exact real-space coarse-graining and conformal compactification while clearly separating a finite-step displacement from a continuous field-theoretic beta function.
\end{abstract}

\section{Introduction}
The renormalization group organizes physical models by scale. A coarse-graining operation eliminates short-distance variables, after which parameters are adjusted so that the effective model remains in a chosen family. Fixed points represent scale-independent behavior, and the linearization near such points classifies local perturbations.

The zero-field one-dimensional Ising chain is an exact laboratory for a geometric formulation. If $K$ is the dimensionless nearest-neighbor coupling and $g=\tanh K$, elimination of alternate spins gives $g'=g^2$. The physical ferromagnetic finite-temperature interval is $0\leq g<1$: $g=0$ is the uncoupled limit, and $g\to1$ is the zero-temperature limit.

We represent this dynamics on a compact space. Inverse stereographic projection identifies the real line with the unit circle minus one point. Under that identification, squaring becomes an explicit rational circle map. The result is an exact conjugacy rather than a perturbative or visual analogy.

\section{Ising decimation and a discrete beta observable}
For spins $\sigma_i\in\{-1,1\}$, the nearest-neighbor bond factor admits the high-temperature form
\[
e^{K\sigma_i\sigma_{i+1}}=\cosh K\bigl(1+g\sigma_i\sigma_{i+1}\bigr),\qquad g=\tanh K.
\]
When an intermediate spin is summed out, terms odd in that spin cancel and the product of the two adjacent bond coordinates survives. For identical bonds, the effective coordinate is therefore $g'=g^2$.

\begin{definition}[Ising decimation map]
For $g\in\mathbb R$, define
\[
R(g)=g^2.
\]
\end{definition}

\begin{definition}[Discrete one-step beta observable]
Define the displacement under one blocking step by
\[
B(g)=R(g)-g=g^2-g.
\]
\end{definition}

The qualifier ``discrete'' is essential. For a continuous semigroup $R_t$, a beta function is normally the infinitesimal generator $\left.\frac{d}{dt}R_t(g)\right|_{t=0}$. The present $B$ instead records one finite decimation step.

\section{Stereographic compactification}
Let $S^1=\{(x,y)\in\mathbb R^2:x^2+y^2=1\}$.

\begin{definition}[Inverse stereographic map]
Define $S:\mathbb R\to\mathbb R^2$ by
\[
S(g)=\left(\frac{2g}{1+g^2},\frac{1-g^2}{1+g^2}\right).
\]
\end{definition}

The denominator is positive for every real $g$. We have $S(0)=(0,1)$, $S(1)=(1,0)$, $S(-1)=(-1,0)$, and $S(g)\to(0,-1)$ as $|g|\to\infty$. Thus the south pole compactifies the two ends of the real line.

\begin{theorem}[Unit-circle image]
For every $g\in\mathbb R$, $S(g)\in S^1$; explicitly,
\[
\left(\frac{2g}{1+g^2}\right)^2+\left(\frac{1-g^2}{1+g^2}\right)^2=1.
\]
\end{theorem}
\begin{proof}
Putting both terms over $(1+g^2)^2$, the numerator is
\[
4g^2+(1-g^2)^2=1+2g^2+g^4=(1+g^2)^2.
\]
The denominator is nonzero, so the quotient equals one.
\end{proof}

On $S^1\setminus\{(0,-1)\}$ the inverse chart is $g=x/(1+y)$. Substitution of $S(g)$ recovers $g$, showing that $S$ is a bijective coordinate identification between the real line and the punctured circle.

\section{The induced rational circle map}
\begin{definition}[Rational circle update]
For $(x,y)$ with nonzero denominators, set
\[
C(x,y)=\left(\frac{x^2}{2-x^2},\frac{2y}{1+y^2}\right).
\]
\end{definition}
On $S^1$, $2-x^2\geq1$ and $1+y^2\geq1$, so $C$ is defined everywhere on the circle.

\begin{theorem}[Stereographic conjugacy]
For every $g\in\mathbb R$,
\[
S(R(g))=C(S(g)).
\]
Thus Ising decimation on the finite coupling line and the rational map on the punctured circle are conjugate.
\end{theorem}
\begin{proof}
Write $x=2g/(1+g^2)$ and $y=(1-g^2)/(1+g^2)$. For the first coordinate,
\begin{align*}
\frac{x^2}{2-x^2}
&=\frac{4g^2/(1+g^2)^2}{2-4g^2/(1+g^2)^2}\\
&=\frac{2g^2}{(1+g^2)^2-2g^2}
=\frac{2g^2}{1+g^4}.
\end{align*}
For the second coordinate,
\begin{align*}
\frac{2y}{1+y^2}
&=\frac{2(1-g^2)(1+g^2)}{(1+g^2)^2+(1-g^2)^2}\\
&=\frac{1-g^4}{1+g^4}.
\end{align*}
Consequently
\[
C(S(g))=\left(\frac{2g^2}{1+g^4},\frac{1-g^4}{1+g^4}\right)=S(g^2)=S(R(g)).
\]
All denominators are positive.
\end{proof}

\begin{corollary}[Circle preservation on the stereographic image]
For every real $g$, the point $C(S(g))$ lies on $S^1$.
\end{corollary}
\begin{proof}
The conjugacy gives $C(S(g))=S(g^2)$, and the unit-circle theorem applies to $g^2$.
\end{proof}

\section{Fixed couplings and flow direction}
\begin{theorem}[Finite fixed-coupling classification]
For $g\in\mathbb R$, $B(g)=0$ if and only if $g=0$ or $g=1$.
\end{theorem}
\begin{proof}
The factorization $B(g)=g(g-1)$ has exactly the stated real zeros, and direct substitution verifies both.
\end{proof}

The fixed couplings map to $S(0)=(0,1)$ and $S(1)=(1,0)$. The south pole represents infinite coupling and is not a finite zero of $B$.

\begin{proposition}[Physical one-step contraction]
If $0<g<1$, then $0<R(g)<g$ and $B(g)<0$.
\end{proposition}
\begin{proof}
We have $g^2>0$, and multiplying $g<1$ by positive $g$ gives $g^2<g$.
\end{proof}
Thus every interior physical coupling moves toward weak coupling. Repeated squaring suggests the extension $R^n(g)=g^{2^n}$, but the exact results here concern the one-step map.

\section{Linearization}
\begin{theorem}[Derivative of the Ising update]
For every $g\in\mathbb R$, $R$ is differentiable at $g$ and
\[
R'(g)=2g.
\]
\end{theorem}
\begin{proof}
For $h\neq0$,
\[
\frac{R(g+h)-R(g)}{h}=\frac{(g+h)^2-g^2}{h}=2g+h,
\]
which tends to $2g$ as $h\to0$.
\end{proof}

The multiplier is $0$ at the weak-coupling fixed point and $2$ at the boundary fixed point. The first is strongly contracting, while the second expands perturbations in the unrestricted real coordinate.

\begin{theorem}[Derivative of the discrete beta observable]
For every $g\in\mathbb R$, $B$ is differentiable and
\[
B'(g)=2g-1.
\]
\end{theorem}
\begin{proof}
Differentiate $B(g)=g^2-g$ term by term.
\end{proof}
The derivative vanishes at $g=1/2$, where $B(1/2)=-1/4$. Since $B''(g)=2$, this is the minimum displacement on the physical interval.

Under a differentiable coordinate change $u=h(g)$, the transformed update is $\widetilde R=h\circ R\circ h^{-1}$ and
\[
\widetilde R'(h(g))=\frac{h'(R(g))}{h'(g)}R'(g),
\]
when $h'(g)\neq0$. At a fixed point the chart factors cancel. Fixed-point multipliers are therefore invariant under regular one-dimensional conjugacies, while derivatives away from fixed points are coordinate dependent.

\section{Numerical algorithms and examples}
Direct evaluation uses constant time and memory per coupling. Representative exact values are
\[
R(0)=0,\quad R(1/4)=1/16,\quad R(1/2)=1/4,\quad R(3/4)=9/16,\quad R(1)=1.
\]
The associated data are shown in Table~\ref{tab:data}.
\begin{table}[h]
\centering
\begin{tabular}{ccccc}
\toprule
$g$ & $R(g)$ & $B(g)$ & $R'(g)$ & $B'(g)$\\
\midrule
$0$ & $0$ & $0$ & $0$ & $-1$\\
$1/4$ & $1/16$ & $-3/16$ & $1/2$ & $-1/2$\\
$1/2$ & $1/4$ & $-1/4$ & $1$ & $0$\\
$3/4$ & $9/16$ & $-3/16$ & $3/2$ & $1/2$\\
$1$ & $1$ & $0$ & $2$ & $1$\\
\bottomrule
\end{tabular}
\caption{One-step update, displacement, and derivatives.}
\label{tab:data}
\end{table}

A numerical conjugacy diagnostic computes $P_1=S(R(g))$ and $P_2=C(S(g))$, then reports $\|P_1-P_2\|_2$. A second diagnostic reports $|x^2+y^2-1|$ for $(x,y)=S(g)$. For $N$ inputs, both procedures have $O(N)$ time complexity and $O(1)$ auxiliary memory when streamed. Floating-point residuals illustrate the exact identities but do not replace their algebraic proofs.

\section{Conformal and dynamical interpretation}
Stereographic projection is conformal wherever its chart is regular. In a one-dimensional coupling space the immediate gains are rational parametrization and compactification rather than nontrivial angle preservation. The construction nevertheless provides an architecture for higher dimensions: compactify the coupling space, transport the update by conjugacy, and separate invariant dynamical data from chart-dependent formulas.

Writing $g=\tan(\theta/2)$ gives
\[
S(g)=(\sin\theta,\cos\theta),\qquad
\tan\left(\frac{\theta'}2\right)=\tan^2\left(\frac\theta2\right).
\]
On $0\leq g\leq1$, one has $0\leq\theta\leq\pi/2$; interior points move toward the north pole. The Cartesian rational map avoids the branch choices inherent in inverse trigonometric coordinates.

The circle map extends to the south pole, where $C(0,-1)=(0,-1)$. This is a compactified fixed point corresponding to infinity, not an additional finite solution of $B(g)=0$. The distinction is essential when interpreting compact phase portraits.

\section{Applications and limitations}
The circle gives a bounded global portrait of weak, strong, and negative couplings. It offers a clean benchmark for geometric RG proposals: a proposed chart should land on its claimed manifold, the induced map should be globally defined on the relevant image, and the conjugacy should hold.

The result has precise limitations. First, $B(g)$ is a finite-step displacement, not an infinitesimal generator. Second, derivatives away from fixed points depend on the coupling coordinate. Third, no identity for four-dimensional $\phi^4$ theory follows from this solvable example. Such a comparison requires a fixed dimension, regulator, subtraction scheme, normalization, and perturbative order. Local conjugacy near a hyperbolic fixed point is a more natural coordinate-aware target than literal equality of formulas from unrelated schemes.

The core identities are global for every finite real $g$ and require no approximation. By contrast, iteration and convergence, continuous semigroups, changing stereographic poles, and field-theory comparisons are extensions rather than assumptions in the established statements.

\section{Future work}
Several extensions follow naturally. One may prove $R^n(g)=g^{2^n}$ and convergence to zero for $0\leq g<1$, then transport convergence through $S$. One may derive $g'=g^2$ from spin summation or a transfer matrix while tracking the free-energy normalization. Introducing a continuous semigroup would produce a genuine infinitesimal beta function.

Allowing the stereographic pole to vary leads to scale-dependent M\"obius transformations and cocycle conditions. Finally, a comparison with $\phi^4$ theory should be attempted only after fixing the physical and renormalization conventions; local flow conjugacy is a plausible invariant objective.

\section{Conclusion}
The Ising decimation map $R(g)=g^2$ is globally conjugate, through inverse stereographic projection, to the rational circle map
\[
C(x,y)=\left(\frac{x^2}{2-x^2},\frac{2y}{1+y^2}\right).
\]
The finite fixed couplings are precisely $0$ and $1$, the update derivative is $2g$, and the derivative of the discrete displacement is $2g-1$. Coarse-graining on the coupling line and rational dynamics on the circle are therefore the same exact one-step transformation viewed in two coordinate systems.

